(async () => {
  const E = window.__editor; await E.app.ready; await E.ready3d;
  const F = await import('/src/engine/level/LevelFormat.js');
  const C = await import('/src/engine/level/ObjectCatalog.js');
  const K = await import('/src/engine/level/StoryChecks.js');
  const S = await import('/src/editor/story.js');
  const R = window.R = { E, F, C, K, S, fails: [], orig: F.serializeLevel(E.state.level), msgs: [] };
  R.ok = (c, m) => { if (!c) { R.fails.push(m); setTimeout(() => { throw new Error('ASSERT ' + m); }); } return !!c; };
  // (a step that throws fails the run too: the old code lacks some of the functions used here)
  R.step = async (name, fn) => { try { return await fn(); } catch (e) { R.ok(false, name + ' threw: ' + (e?.message ?? e)); return String(e?.stack ?? e); } };
  R.settle = async () => { await T.sleep(150); while (E.view3d?.busy) await T.sleep(100); await T.sleep(250); };
  R.obj = (id) => E.state.getObject(id);
  E.state.on('status', (m) => R.msgs.push(m));
  R.last = () => R.msgs[R.msgs.length - 1] ?? '';
  // the problems under an inspector field, one per line ([] while hidden; null: no such element)
  R.hint = (label) => { const i = T.field(label)?.closest('.le-field')?.querySelector('.le-field-issue'); return !i ? null : i.hidden ? [] : i.textContent.split('\n'); };
  // what Check for problems says about one field of one object
  R.checks = (id, field) => K.storyIssues(E.state.level, S.storyCheckContext(E.state)).filter((i) => i.id === id && i.field === field).map((i) => i.msg);
  R.row = (id) => document.querySelector(`.le-outliner .le-row-item[data-id="${id}"]`);
  R.group = (label) => [...document.querySelectorAll('.le-outliner .le-group')].find((g) => g.querySelector('.le-group-label')?.textContent === label);
  R.set = async (label, v) => { T.setInput(T.field(label), v); await T.sleep(150); return R.hint(label); };
  E.state.setTool('select');
  E.state.setView({ layout: 'split', storyPreview: false, storyValues: '', hiddenTypes: [] });
  return JSON.stringify({ level: E.state.level.name, bytes: R.orig.length });
})()

R.step('hint', async () => {
  const { E } = R; const st = E.state; const sp = st.level.spawn;
  const m = st.addObject('marker', sp.x + 3, sp.z + 3, {}, { select: false });
  const ev = st.addObject('event', sp.x + 6, sp.z + 3, { minX: sp.x + 5, maxX: sp.x + 7, minZ: sp.z + 2, maxZ: sp.z + 4, on: 'use', run: ['once greet-once', '  : Hello.'] }, { select: false });
  const ex = st.addObject('exit', sp.x + 9, sp.z + 3, { to: 'nowhere', minX: sp.x + 8, maxX: sp.x + 10, minZ: sp.z + 2, maxZ: sp.z + 4 }, { select: false });
  R.m = m.id; R.ev = ev.id; R.ex = ex.id;
  const W = 'Story: only when';
  const out = {};
  st.select([m.id]); await T.sleep(300);
  let h = out.gold = await R.set(W, 'gold');
  R.ok(h?.length === 1 && /reserved word/.test(h[0]) && /can never be set/.test(h[0]) && /gold > 0/.test(h[0]), 'when: gold — the hint: a flag that can never be set, write "gold > 0"');
  R.ok(R.checks(m.id, 'when').some((c) => c.endsWith(h?.[0] ?? '\u0000')), '…in the words of Check for problems');
  h = out.day = await R.set(W, 'Day');
  R.ok(h?.length === 1 && /day > 1/.test(h[0]), 'when: Day — a reserved word in any case');
  h = out.parse = await R.set(W, 'met-hollis and (');
  R.ok(h?.length === 1 && /read as one flag named/.test(h[0]) && R.checks(m.id, 'when').some((c) => c.endsWith(h[0])), 'a condition that does not parse: the checks\' words');
  h = await R.set(W, 'met-hollis');
  R.ok(h?.length === 0 && R.checks(m.id, 'when').length === 0, 'a flag name is fine');
  h = await R.set(W, 'gold > 0 and not true');
  R.ok(h?.length === 0, 'a comparison is fine');
  h = out.done = await R.set(W, 'done:nothing-here');
  R.ok(h?.length === 1 && /^done:nothing-here names no "once" event/.test(h[0]) && /of this level/.test(h[0]) && R.checks(m.id, 'when').includes(h[0]), 'done: of no once event or block — the warning of Check for problems');
  h = await R.set(W, 'done:greet-once');
  R.ok(h?.length === 0, 'done: of a once block of this level is fine');
  h = out.notOnce = await R.set(W, `done:${ev.id}`);
  R.ok(h?.length === 1 && /not "once"/.test(h[0]), 'done: of an event that is not once');
  h = out.unless = await R.set('Story: gone when', 'weather');
  R.ok(h?.length === 1 && /weather = rain/.test(h[0]), 'unless: weather — the flag rule too');
  // an event's `if`: the script rule (`gold` reads the purse)
  st.select([ev.id]); await T.sleep(300);
  h = out.evIf = await R.set('Condition', 'gold');
  R.ok(h?.length === 0 && R.checks(ev.id, 'if').length === 0, 'an event\'s if: gold is fine (the script rule)');
  h = await R.set('Condition', 'gold and (');
  R.ok(h?.length === 1 && !/read as one flag/.test(h[0]) && R.checks(ev.id, 'if').some((c) => c.endsWith(h[0])), 'if: a condition that does not parse');
  h = await R.set(W, 'gold');
  R.ok(h?.length === 1 && /reserved word/.test(h[0]), 'the same event\'s when: gold — the flag rule');
  // an exit's `requires` (a text field in the catalog): the flag rule, with the hint
  st.select([ex.id]); await T.sleep(300);
  h = out.req = await R.set('Open only with story flag', 'gold');
  R.ok(h?.length === 1 && /reserved word/.test(h[0]) && R.checks(ex.id, 'requires').some((c) => c.endsWith(h[0])), 'an exit\'s requires: gold — the flag rule, as the checks read it');
  R.ok(!!T.field('Open only with story flag')?.closest('.le-field')?.classList.contains('is-condition'), 'requires is edited as a condition');
  const lines = E.app._softWarnings().filter((l) => l.startsWith('Story'));
  R.ok(lines.some((l) => l.includes(`marker ${m.id} › unless`) && /reserved word/.test(l)) && lines.some((l) => l.includes(`exit ${ex.id} › requires`) && /reserved word/.test(l)), 'Check for problems reports them');
  return JSON.stringify(out);
})

R.step('campaign', async () => {
  const { E, S } = R; const st = E.state;
  await E.app.openProject('mill-road', { confirm: false, campaign: 'ferrymans-lantern' });
  await E.ready3d;
  await S.campaignStoryContext('ferrymans-lantern'); await T.sleep(200);
  const ctx = S.storyCheckContext(st);
  const evs = ctx.events ?? new Map();
  R.ok(ctx.level === 'mill-road', 'the context names the level');
  R.ok(evs.get('millbrook.ev_planks') === true && evs.get('millbrook.ev_lamps') === false && evs.get('millbrook.ev_welcome') === true && evs.get('old-quarry.ev_cleared') === true && evs.get('mill-cellar.ev_chart') === false, 'every level file\'s events (a chapter variant\'s under its base level), once or not');
  R.ok(evs.get('mill-road.ev_ford') === true && evs.get('story.ford-open') === true && evs.get('story.count-places') === false, 'the open level\'s and the story files\' events');
  R.ok(!!ctx.onceKeys?.has('hollis-asks'), 'the story scripts\' once keys');
  const sp = st.level.spawn;
  const m = st.addObject('marker', sp.x + 2, sp.z, {}, { select: false });
  R.mm = m.id;
  st.select([m.id]); await T.sleep(300);
  const W = 'Story: only when';
  const out = {};
  for (const [cond, want] of [
    ['done:millbrook.ev_planks', ''], ['done:ford-open', ''], ['done:hollis-asks', ''], ['done:ev_ford', ''], ['done:mill-road.ev_ford', ''],
    ['done:millbrook.ev_lamps', 'not "once"'], ['done:count-places', 'not "once"'], ['done:no-such-key', 'of the campaign'], ['done:millbrook.ev_nope', 'of the campaign'],
  ]) {
    const h = await R.set(W, cond);
    const c = R.checks(m.id, 'when');
    out[cond] = h;
    R.ok(want ? h?.length === 1 && h[0].includes(want) && c.includes(h[0]) : h?.length === 0 && c.length === 0, `${cond}: ${want || 'fine'} (the hint and Check for problems agree)`);
  }
  // the open level as edited, not its file: without its event, done:ev_ford names nothing
  st.removeObjects(['ev_ford']); st.select([m.id]); await T.sleep(300);
  const gone = out.deleted = await R.set(W, 'done:ev_ford');
  R.ok(gone?.length === 1 && gone[0].includes('of the campaign'), 'the open level\'s events as edited: ev_ford deleted, done:ev_ford names nothing');
  st.undo(); st.undo(); await T.sleep(200);
  R.ok(!!R.obj('ev_ford'), 'ev_ford back');
  return JSON.stringify(out);
})

R.step('fallback', async () => {
  const { E, S } = R; const st = E.state;
  const W = 'Story: only when';
  st.select([R.mm]); await T.sleep(300);
  await R.set(W, 'done:no-such-key');
  // a level file that cannot be read: no events — done: keys are read as before (no warning)
  const real = window.fetch;
  window.fetch = async (u, o) => (/\/campaigns\/ferrymans-lantern\/levels\/old-quarry\.json$/.test(String(u)) ? new Response('missing', { status: 404 }) : real(u, o));
  try { await S.campaignStoryContext('ferrymans-lantern', { refresh: true }); } finally { window.fetch = real; }
  await T.sleep(300);
  const ctx = S.storyCheckContext(st);
  R.ok(ctx.events === undefined && ctx.onceKeys === undefined && ctx.items instanceof Set && ctx.level === 'mill-road', 'a level file that cannot be read: no events (the story files still count)');
  R.ok(R.hint(W)?.length === 0 && R.checks(R.mm, 'when').length === 0, 'done: keys then pass as before');
  await S.campaignStoryContext('ferrymans-lantern', { refresh: true }); await T.sleep(300);
  R.ok(!!R.hint(W)?.[0]?.includes('of the campaign'), 'read again: the hint follows by itself');
  await E.app.validate(); await T.sleep(400);
  const lines = [...document.querySelectorAll('.le-dialog .le-dialog-list li')].map((x) => x.textContent);
  R.ok(lines.some((l) => l.includes(`marker ${R.mm} › when`) && l.includes('done:no-such-key names no')), 'Check for problems lists the done: warning');
  T.clickText('.le-dialog .le-btn', 'OK'); await T.sleep(300);
  let n = 0; while (st.canUndo && n < 50) { st.undo(); n++; }
  const text = await fetch('/campaigns/ferrymans-lantern/levels/mill-road.json', { cache: 'no-store' }).then((r) => r.text());
  R.ok(R.F.serializeLevel(st.level) === text && !st.dirty, 'Mill Road as its file');
  // a chapter variant reads done: keys as the level it stands for
  await E.app.openProject('millbrook-dusk', { confirm: false, campaign: 'ferrymans-lantern' });
  await E.ready3d; await T.sleep(200);
  R.ok(S.storyCheckContext(st).level === 'millbrook', 'millbrook-dusk checks as millbrook');
  const sp = st.level.spawn;
  const m = st.addObject('marker', sp.x + 2, sp.z, {}, { select: false });
  st.select([m.id]); await T.sleep(300);
  const a = await R.set(W, 'done:ev_planks');
  const b = await R.set(W, 'done:ev_welcome');
  const c = await R.set(W, 'done:ev_lamps');
  R.ok(a?.length === 0 && b?.length === 0 && c?.length === 1 && c[0].includes('not "once"'), 'its own events and its base level\'s');
  n = 0; while (st.canUndo && n < 50) { st.undo(); n++; }
  const dusk = await fetch('/campaigns/ferrymans-lantern/levels/millbrook-dusk.json', { cache: 'no-store' }).then((r) => r.text());
  R.ok(R.F.serializeLevel(st.level) === dusk && !st.dirty, 'Millbrook at dusk as its file');
  return JSON.stringify({ lines: lines.filter((l) => l.includes(R.mm)) });
})

R.step('hidden', async () => {
  const { E } = R; const st = E.state;
  await E.app.openProject('emberfall', { confirm: false }); await E.ready3d; await R.settle();
  const sp = st.level.spawn;
  const t1 = st.addObject('tree', sp.x - 2.5, sp.z + 3, { when: 'x' }, { select: false });
  const t2 = st.addObject('tree', sp.x + 1.5, sp.z + 3, {}, { select: false });
  R.t1 = t1.id; R.t2 = t2.id;
  E.view2d.focusOn(sp.x, sp.z + 3, { scale: 36 });
  st.setView({ storyPreview: true, storyValues: '' }); await R.settle();
  const out = {};
  const want = `${t1.id} is hidden by the story preview (no values) — turn the preview off to edit it`;
  const row = R.row(t1.id);
  R.ok(!!row?.classList.contains('is-hidden'), 'the hidden tree\'s outliner row is dimmed');
  st.select([t2.id]); await T.sleep(100);
  row.click(); await T.sleep(100);
  out.click = R.last();
  R.ok(JSON.stringify(st.selection) === JSON.stringify([t2.id]) && R.last().startsWith(want) && /double-click/.test(R.last()), 'a click on a dimmed outliner row selects nothing; the status bar says why');
  row.dispatchEvent(new MouseEvent('click', { bubbles: true, ctrlKey: true })); await T.sleep(50);
  row.dispatchEvent(new MouseEvent('click', { bubbles: true, shiftKey: true })); await T.sleep(50);
  R.ok(JSON.stringify(st.selection) === JSON.stringify([t2.id]), 'nor a Ctrl / Shift + click');
  st.select([]);
  R.group(R.C.OBJECT_TYPES.tree.label).dispatchEvent(new MouseEvent('click', { bubbles: true, shiftKey: true })); await T.sleep(100);
  out.group = R.last();
  R.ok(st.selection.includes(t2.id) && !st.selection.includes(t1.id) && R.last().startsWith(`${t1.id} was left out: hidden by the story preview`), 'Shift+click on the Tree group leaves the hidden tree out and says so');
  st.select([]); E.app.run('edit.selectAll'); await T.sleep(50);
  out.all = R.last();
  R.ok(st.selection.length > 1 && !st.selection.includes(t1.id) && R.last().includes(`${t1.id} was left out`), 'Ctrl+A leaves it out and says so');
  st.select([t1.id, t2.id]);
  R.ok(JSON.stringify(st.selection) === JSON.stringify([t2.id]), 'select() never takes a hidden object');
  st.select([]);
  await T.click(t1.x, t1.z); await T.sleep(50);
  out.map = R.last();
  R.ok(!st.selection.length && R.last() === want, 'a click on its place in the 2D map selects nothing and says why');
  await T.click(t1.x, t1.z, { ctrl: true }); await T.sleep(50);
  R.ok(!st.selection.length && R.last() === want, 'so does a Ctrl+click');
  // (from open ground: above the lamppost and the birds' yard)
  await T.drag([[sp.x - 3.5, sp.z + 2.6], [sp.x + 3, sp.z + 4.4]]); await T.sleep(50);
  R.ok(!st.inTransaction && !st.canRedo && st.undoLabel === 'Add Tree', 'the box moved nothing');
  out.box = R.last();
  R.ok(st.selection.includes(t2.id) && !st.selection.includes(t1.id) && R.last().includes(`${t1.id} was left out`), 'a box over both selects the shown one and says why the other was left out');
  return JSON.stringify(out);
})

R.step('edits', async () => {
  const { E } = R; const st = E.state;
  st.setView({ storyValues: 'x' }); await R.settle();
  st.select([R.t1]); await T.sleep(300);
  R.ok(JSON.stringify(st.selection) === JSON.stringify([R.t1]), 'shown with the value x: selectable');
  T.setInput(T.field('Story: only when'), 'y'); await T.sleep(300);
  const out = { edit: R.last() };
  R.ok(R.obj(R.t1).when === 'y', 'the edit applies');
  R.ok(!st.selection.includes(R.t1), 'editing its when so that the preview hides it deselects it');
  R.ok(R.last() === `${R.t1} left the selection: hidden by the story preview (x) — turn the preview off to edit it`, 'and the status bar says why');
  R.ok(document.querySelector('.le-inspector .le-panel-note')?.textContent === 'Level', 'the inspector shows the level');
  st.undo(); await T.sleep(200);
  R.ok(R.obj(R.t1).when === 'x' && JSON.stringify(st.selection) === JSON.stringify([R.t1]), 'undo: shown and selected again');
  st.redo(); await T.sleep(200);
  R.ok(R.obj(R.t1).when === 'y' && !st.selection.includes(R.t1), 'redo: hidden, not selected');
  // undo of a selection-changing step taken while it was shown
  st.setView({ storyPreview: false }); await T.sleep(100);
  st.select([R.t1]); E.app.run('edit.delete'); await T.sleep(200);
  R.ok(!R.obj(R.t1), 'deleted while shown');
  st.setView({ storyPreview: true }); await R.settle();
  st.undo(); await T.sleep(200);
  R.ok(!!R.obj(R.t1) && !st.selection.includes(R.t1), 'undo of the delete does not select it while the preview hides it');
  st.redo(); await T.sleep(100); st.undo(); await T.sleep(200);
  R.ok(!!R.obj(R.t1) && !st.selection.includes(R.t1), 'nor redo, undo');
  // the weather (a level setting) changes what is hidden too
  st.setView({ storyValues: 'x' }); await T.sleep(100);
  st.updateObject(R.t1, (o) => { o.when = 'weather = clear'; }, 'Story'); await T.sleep(100);
  st.select([R.t1]); await T.sleep(100);
  R.ok(JSON.stringify(st.selection) === JSON.stringify([R.t1]), 'shown in clear weather');
  st.setLevelProps({ environment: { weather: 'rain' } }, 'Weather'); await T.sleep(200);
  R.ok(!st.selection.includes(R.t1), 'rain hides it: it leaves the selection');
  st.undo(); st.undo(); await T.sleep(200);
  // a paste of objects the views hide: pasted, not selected
  st.setView({ storyPreview: false }); await T.sleep(100);
  const copies = [JSON.parse(JSON.stringify(R.obj(R.t1))), JSON.parse(JSON.stringify(R.obj(R.t2)))];
  st.setView({ storyPreview: true }); await T.sleep(100);
  const n0 = st.level.objects.length;
  E.app.paste(copies); await T.sleep(200);
  const added = st.level.objects.slice(n0).map((o) => o.id);
  out.paste = R.last();
  R.ok(added.length === 2 && JSON.stringify(st.selection) === JSON.stringify([added[1]]), 'a paste selects only the pasted objects the views show');
  R.ok(R.last().startsWith('Pasted 2 objects · ') && R.last().includes(`${added[0]} is not selected`), 'and says why');
  st.undo(); await T.sleep(200);
  return JSON.stringify(out);
})

R.step('reveal', async () => {
  const { E } = R; const st = E.state;
  const label = R.C.OBJECT_TYPES.tree.label;
  st.setView({ storyPreview: false }); await R.settle();
  st.select([R.t1, R.t2]); await T.sleep(200);
  R.group(label).querySelector('.le-eye').click(); await R.settle();
  const out = { eye: R.last() };
  R.ok(!st.selection.length && R.last() === `2 objects hidden by the outliner's eye (${label} objects) left the selection — show ${label} objects again to edit them`, 'hiding the type deselects its objects and says why');
  R.row(R.t2).click(); await T.sleep(100);
  out.row = R.last();
  R.ok(!st.selection.length && R.last().startsWith(`${R.t2} is hidden by the outliner's eye (${label} objects) — show ${label} objects again to edit it`), 'a click on its dimmed row says why');
  R.row(R.t2).dispatchEvent(new MouseEvent('dblclick', { bubbles: true })); await R.settle();
  R.ok(!(st.view.hiddenTypes ?? []).includes('tree') && JSON.stringify(st.selection) === JSON.stringify([R.t2]), 'a double-click on the dimmed row shows the type again and selects it');
  R.ok(R.last() === `Type shown again — ${R.t2} selected`, 'and says so');
  st.setView({ storyPreview: true, storyValues: 'x' }); await R.settle();
  R.ok(!!R.row(R.t1)?.classList.contains('is-hidden') && st.selection.length === 1, 'the story preview hides the tree with when y');
  R.row(R.t1).dispatchEvent(new MouseEvent('dblclick', { bubbles: true })); await R.settle();
  out.dbl = R.last();
  R.ok(st.view.storyPreview === false && JSON.stringify(st.selection) === JSON.stringify([R.t1]) && /story preview off/i.test(R.last()), 'a double-click on a row the story preview hides turns the preview off and selects it');
  // both reasons at once
  st.setView({ storyPreview: true, hiddenTypes: ['tree'] }); await R.settle();
  R.row(R.t1).click(); await T.sleep(100);
  out.both = R.last();
  R.ok(R.last().startsWith(`${R.t1} is hidden by the outliner's eye (${label} objects) and the story preview (x) — show ${label} objects again and turn the preview off to edit it`), 'both reasons named');
  R.row(R.t1).dispatchEvent(new MouseEvent('dblclick', { bubbles: true })); await R.settle();
  R.ok(st.view.storyPreview === false && !(st.view.hiddenTypes ?? []).length && JSON.stringify(st.selection) === JSON.stringify([R.t1]), 'a double-click turns both off');
  // the Place tool: a tree placed while trees are hidden is placed, not selected, and the status says why
  st.setView({ hiddenTypes: ['tree'] }); await R.settle();
  st.setToolOption('objectType', 'tree'); st.setTool('place');
  const n0 = st.level.objects.length; const sp = st.level.spawn;
  await T.click(sp.x + 4, sp.z + 5); await T.sleep(100);
  const placed = st.level.objects[n0];
  out.place = R.last();
  R.ok(st.level.objects.length === n0 + 1 && placed?.type === 'tree' && !st.selection.length && R.last().startsWith(`Placed ${label} (${placed?.id}) · ${placed?.id} is hidden by the outliner's eye`), 'a tree placed while trees are hidden: not selected, and the status says why');
  st.undo(); st.setTool('select'); st.setView({ hiddenTypes: [] }); await R.settle();
  return JSON.stringify(out);
})

R.step('background', async () => {
  const { E } = R; const st = E.state; const sp = st.level.spawn;
  const M = await import('/src/editor/map2d/Map2DView.js');
  const a = st.addObject('event', sp.x + 6, sp.z + 3, { minX: sp.x + 5, maxX: sp.x + 7, minZ: sp.z + 2, maxZ: sp.z + 4, on: 'enter', label: 'Bark', run: ['toast Hi'] }, { select: false });
  st.updateObject(a.id, (o) => { o.background = true; }, 'Background');
  await R.settle();
  const tag = M.eventTag(R.obj(a.id));
  const lab = E.view3d.actors.entries.get(a.id)?.label;
  const text3d = lab?.el?.textContent ?? '';
  R.ok(tag === '! enter · Bark (background)', 'the 2D tag says "(background)"');
  R.ok(text3d.includes('(background)'), 'so does the 3D label');
  st.updateObject(a.id, (o) => { delete o.background; }, 'Background'); await R.settle();
  R.ok(M.eventTag(R.obj(a.id)) === '! enter · Bark' && !(E.view3d.actors.entries.get(a.id)?.label?.el?.textContent ?? '').includes('(background)'), 'without it: the usual tag');
  st.undo(); await R.settle();
  E.view2d.focusOn(sp.x + 6, sp.z + 3, { scale: 40 }); await R.settle();
  return JSON.stringify({ tag, text3d });
})

R.step('end', async () => {
  const { E } = R; const st = E.state;
  st.setView({ storyPreview: false, storyValues: '', hiddenTypes: [] });
  let n = 0; while (st.canUndo && n < 200) { st.undo(); n++; }
  await R.settle();
  R.ok(R.F.serializeLevel(st.level) === R.orig && !st.dirty, 'undo back to the file\'s bytes');
  return JSON.stringify({ undone: n });
})
